async function removeInfrastructureFromCompany(companyId, entityId) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'removeCompanyInfrastructure',
        companyId: companyId,
        entityId: entityId
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to remove infrastructure entity');
    }

    return {
      success: true,
      entityId: entityId,
      companyId: companyId,
      message: `Removed infrastructure entity ${entityId} from company ${companyId}`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
